// Cross-language parity: the Dart engine must reproduce every result of the TypeScript engine.
//
// Fixtures: packages/engine/fixtures/parity.json (generated by generate-parity.mjs from the TypeScript
// source; shared by every port) and, when present, the Go port's extra corner cases
// (packages/sdk-go/internal/testdata/extra.json, or go/internal/testdata/extra.json in the public
// repository), whose evaluation error messages (V8's TypeError texts) are compared as well.
// Override the locations with NANOFLAGS_PARITY_FIXTURES / NANOFLAGS_PARITY_EXTRA.
@TestOn('vm')
library;

import 'dart:convert';
import 'dart:io';

import 'package:nanoflags/engine.dart';
import 'package:test/test.dart';

import 'support/parity_compare.dart';

File? _find(String env, List<String> candidates) {
  final override = Platform.environment[env];
  if (override != null && override.isNotEmpty) return File(override);
  for (final c in candidates) {
    final f = File(c);
    if (f.existsSync()) return f;
  }
  return null;
}

void main() {
  final parity = _find('NANOFLAGS_PARITY_FIXTURES', ['../../engine/fixtures/parity.json', '../../../packages/engine/fixtures/parity.json']);
  if (parity == null) {
    test('parity fixtures', () {}, skip: 'packages/engine/fixtures/parity.json not found');
    return;
  }
  final doc = jsonDecode(parity.readAsStringSync()) as Map<String, dynamic>;

  test('fixture engine version and counts', () {
    expect(doc['engineVersion'], engineVersion);
    expect((doc['counts'] as Map)['cases'], (doc['cases'] as List).length);
  });

  test('murmur3 vectors', () {
    final cases = (doc['murmur3'] as List).cast<Map<String, dynamic>>();
    final bad = [for (final c in cases) if (murmur3(c['input'] as String, c['seed'] as int) != c['hash']) c];
    expect(bad, isEmpty, reason: bad.take(5).toString());
    expect(cases.length, greaterThan(300));
    printOnFailure('${cases.length} murmur3 vectors');
  });

  test('bucket vectors', () {
    final cases = (doc['buckets'] as List).cast<Map<String, dynamic>>();
    final bad = [for (final c in cases) if (bucketOf(c['seed'] as String, c['identity'] as String) != (c['bucket'] as num).toDouble()) c];
    expect(bad, isEmpty, reason: bad.take(5).toString());
  });

  test('supportsEngine vectors', () {
    for (final c in (doc['supportsEngine'] as List).cast<Map<String, dynamic>>()) {
      expect(supportsEngine(c['bundle']), c['expected'], reason: jsonEncode(c));
    }
  });

  test('clientBundle (browser view) vectors', () {
    final cases = (doc['clientBundle'] as List).cast<Map<String, dynamic>>();
    for (final c in cases) {
      final got = clientBundle((c['bundle'] as Map).cast<String, Object?>());
      expect(jsonEquals(got, c['expected']), isTrue, reason: 'dart=${jsonEncode(got)} ts=${jsonEncode(c['expected'])}');
    }
    expect(cases, isNotEmpty);
  });

  test('every evaluation case', () {
    final cases = (doc['cases'] as List).cast<Map<String, dynamic>>();
    final failures = <String>[];
    for (final c in cases) {
      final p = compareCase(doc, c, messages: false);
      if (p.isNotEmpty) failures.add('${c['name']}: ${p.join('; ')}');
    }
    expect(cases.length, greaterThan(20000));
    expect(failures, isEmpty, reason: '${failures.length} of ${cases.length} cases differ, e.g. ${failures.take(8).join('\n')}');
    print('parity: ${cases.length - failures.length}/${cases.length} evaluation cases identical');
  });

  final extra = _find('NANOFLAGS_PARITY_EXTRA', ['../../sdk-go/internal/testdata/extra.json', '../../../go/internal/testdata/extra.json']);
  test('extra corner cases (Go fixtures, error messages included)', () {
    final x = jsonDecode(extra!.readAsStringSync()) as Map<String, dynamic>;
    final cases = (x['cases'] as List).cast<Map<String, dynamic>>();
    final failures = <String>[];
    for (final c in cases) {
      final p = compareCase(x, c, messages: true);
      if (p.isNotEmpty) failures.add('${c['name']}: ${p.join('; ')}');
    }
    expect(failures, isEmpty, reason: '${failures.length} of ${cases.length} cases differ, e.g. ${failures.take(8).join('\n')}');
    print('extra: ${cases.length - failures.length}/${cases.length} cases identical (error messages included)');
  }, skip: extra == null ? 'extra.json not found' : false);
}
